import pandas as pd
import numpy as np

def calculate_macd(price, fast_period, slow_period, signal_period):
  ema_fast = price.ewm(span=fast_period, adjust=False).mean()
  ema_slow = price.ewm(span=slow_period, adjust=False).mean()
  macd = ema_fast - ema_slow
  signal = macd.ewm(span=signal_period, adjust=False).mean()
  return macd, signal

def calculate_cci(high, low, close, period):
  tp = (high + low + close) / 3
  cci = (tp - tp.rolling(window=period).mean()) / (0.015 * tp.rolling(window=period).std())
  return cci

def calculate_williams_r(high, low, close, period):
  highest_high = high.rolling(window=period).max()
  lowest_low = low.rolling(window=period).min()
  wr = -100 * ((highest_high - close) / (highest_high - lowest_low))
  return wr

def trading_strategy(data):
  macd, signal = calculate_macd(data['Close'], 12, 26, 9)
  cci = calculate_cci(data['High'], data['Low'], data['Close'], 20)
  wr = calculate_williams_r(data['High'], data['Low'], data['Close'], 14)

  long_entry = (macd > signal) & (cci < -100) & (wr < -80)
  short_entry = (macd < signal) & (cci > 100) & (wr > -20)

  long_exit = (macd < signal) | (cci > 100) | (wr > -20)
  short_exit = (macd > signal) | (cci < -100) | (wr < -80)

  positions = pd.DataFrame(index=data.index)
